import { spawn } from "node:child_process";
import { tmpdir } from "node:os";

function run(command, args, options) {
  return new Promise((resolve, reject) => {
    const child = spawn(command, args, options);
    const stdout = [];
    const stderr = [];
    child.stdout?.on("data", (chunk) => stdout.push(chunk));
    child.stderr?.on("data", (chunk) => stderr.push(chunk));
    child.on("error", reject);
    child.on("close", (code, signal) => {
      resolve({
        code,
        signal,
        stdout: Buffer.concat(stdout).toString("utf8"),
        stderr: Buffer.concat(stderr).toString("utf8"),
      });
    });
  });
}

export async function report() {
  const lines = [];
  const push = (label, value) => lines.push(label + " " + value);
  const basic = await run("/bin/sh", ["-c", "printf out; printf err >&2; exit 3"], {
    stdio: ["ignore", "pipe", "pipe"],
  });
  push("basic:", [basic.code, basic.signal, basic.stdout, basic.stderr].join("|"));

  const envCwd = await run("/bin/sh", ["-c", "printf '%s|%s' \"$PWD\" \"$FLAG\""], {
    cwd: tmpdir(),
    env: { PATH: process.env.PATH, FLAG: "set" },
    stdio: ["ignore", "pipe", "pipe"],
  });
  push("env-cwd:", envCwd.stdout.endsWith("|set") && envCwd.stdout.startsWith(tmpdir()));

  const missing = await new Promise((resolve) => {
    const child = spawn("definitely-not-a-binary-scriptc-childzoo", [], {
      stdio: ["ignore", "pipe", "pipe"],
    });
    child.on("error", (error) => resolve(error.code + ":" + error.message));
  });
  push("missing:", missing);

  const killed = await new Promise((resolve, reject) => {
    const child = spawn("/bin/sh", ["-c", "sleep 30"], {
      detached: true,
      stdio: ["ignore", "pipe", "pipe"],
    });
    child.on("error", reject);
    child.on("exit", (code, signal) => resolve([child.pid > 0, child.killed, code, signal].join("|")));
    setTimeout(() => child.kill("SIGTERM"), 20);
  });
  push("kill:", killed);
  return lines.join("\n");
}
